<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Authorized career history · CareSys</title><link rel="stylesheet" href="/assets/caresys.css"></head><body><main class="content"><a href="<?= esc($back,'attr') ?>">← Back to requests</a><h1>Authorized career history</h1><p class="notice">Only the candidate-approved entry versions are shown. Confirmation is not a guarantee of suitability. Download or export is not authorized by this grant.</p><?php foreach($entries as $entry): ?><article class="card"><span class="badge"><?= esc($entry['source']) ?></span><?php if($entry['disputed']): ?> <span class="badge disputed">Disputed — review required</span><?php endif ?><?php if($entry['superseded']??false): ?><span class="badge pending">Superseded — renewed authorization required for replacement facts</span><?php endif ?><h2><?= esc($entry['role']) ?> · <?= esc($entry['employer']) ?></h2><p><?= esc($entry['start_period']?:'Date unknown') ?> – <?= esc($entry['end_period']?:'Date unknown') ?> (<?= esc($entry['precision_code']) ?> precision)</p><p><?= nl2br(esc($entry['summary'])) ?></p></article><?php endforeach ?><?php if(!$entries): ?><p class="empty">No entries included in this grant.</p><?php endif ?></main></body></html>
